package com.gomgomapps.math.core;
import java.math.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaDecimalGroupsTest {
 @Test public void normalGradeSixSuppliesHaveAllUnitsPrecisionAndExactBothFormats(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals("na-nied-primary-2024-v1")).findFirst().orElseThrow();Generator g=new Generator(new Random(296));for(String id:List.of(DecimalMeasureGroups.MUL,DecimalMeasureGroups.DIV)){assertTrue(pack.inGrade(id,6));var limits=GlobalCurriculum.limits(pack.id,id,6);List<String> recent=new ArrayList<>();Set<String> units=new HashSet<>(),formats=new HashSet<>();Set<Integer> precision=new HashSet<>();for(int i=0;i<300;i++){Question q=g.next(id,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());var v=DecimalMeasureGroups.read(q);assertNotNull(v);units.add(v.unit());formats.add(q.answerFormat);precision.add(new BigDecimal(v.raw()).scale());Rational x=Expression.number(v.raw()),k=Rational.of(v.groups()),expected=v.multiply()?x.mul(k):x.div(k);String input=q.answerFormat.equals("fraction")?expected.toString():new BigDecimal(v.raw()).multiply(v.multiply()?BigDecimal.valueOf(v.groups()):BigDecimal.ONE).divide(v.multiply()?BigDecimal.ONE:BigDecimal.valueOf(v.groups())).toPlainString();q.answers=new String[]{"poison"};q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of(input)).correct());HelpPlan h=HelpPlan.forQuestion(q);assertFalse(h.canTransfer());assertEquals(v.multiply()?7:q.answerFormat.equals("fraction")?10:8,h.size());assertTrue(h.step(0).accepts(v.multiply()?"mul":"div"));assertFalse(h.step(0).accepts(v.multiply()?"div":"mul"));}assertEquals(Set.of("m","L","kg"),units);assertEquals(Set.of(1,2,3),precision);assertEquals(id.equals(DecimalMeasureGroups.MUL)?Set.of("decimalValue"):Set.of("decimalValue","fraction"),formats);}}
 @Test public void nonterminatingSharingKeepsExactFractionAndShiftedLearnerResultFrames(){Question q=DecimalMeasureGroups.make(DecimalMeasureGroups.DIV,"1.0",3,"L");q.answers=new String[]{"poison"};q.expression="poison";assertTrue(new Checker().check(q,List.of(),List.of("1/3")).correct());assertFalse(new Checker().check(q,List.of(),List.of("0.333")).correct());HelpPlan h=HelpPlan.forQuestion(q);List<String> entries=List.of("div","1.0","3","1","10","10","30","10","1","3");for(int i=0;i<10;i++)assertTrue(h.step(i).accepts(entries.get(i)));assertEquals(Integer.valueOf(8),q.studyGuide.resultNumeratorFrame);assertEquals(Integer.valueOf(9),q.studyGuide.resultDenominatorFrame);q=DecimalMeasureGroups.make(DecimalMeasureGroups.DIV,"99.9",16,"kg");assertTrue(new Checker().check(q,List.of(),List.of("6.24375")).correct());assertFalse(new Checker().check(q,List.of(),List.of("6.244")).correct());}
 @Test public void zeroBoundaryAndMalformedContextCannotUseKeysOrGenericDomesticPlacement(){Checker c=new Checker();Question q=DecimalMeasureGroups.make(DecimalMeasureGroups.MUL,"99.999",99,"m");assertTrue(c.check(q,List.of(),List.of("9899.901")).correct());q=DecimalMeasureGroups.make(DecimalMeasureGroups.DIV,"0.000",99,"kg");assertTrue(c.check(q,List.of(),List.of("0")).correct());for(String id:List.of(DecimalMeasureGroups.MUL,DecimalMeasureGroups.DIV)){assertFalse(Curriculum.inCurriculum(Catalog.get(id),2022));assertEquals(Checker.Status.INPUT_NEEDED,c.check(new Question(id,"broken","","0"),List.of(),List.of("0")).status);}try{DecimalMeasureGroups.make(DecimalMeasureGroups.DIV,"1.0",0,"L");fail();}catch(IllegalArgumentException expected){}assertEquals(300000,DecimalPowerTen.count(DecimalPowerTen.MUL,GlobalCurriculum.limits("england-primary-2021-v1",DecimalPowerTen.MUL,6)));}
 @Test public void fractionErrorPartUsesVisibleContextWithoutBlamingCorrectDenominator(){Question q=DecimalMeasureGroups.make(DecimalMeasureGroups.DIV,"20.5",88,"m");q.answers=new String[]{"poison"};q.expression="poison";assertEquals(1,FractionInput.errorPart(q,"42/176"));assertEquals(2,FractionInput.errorPart(q,"41/177"));assertEquals(0,FractionInput.errorPart(q,"42/177"));assertEquals(0,FractionInput.errorPart(q,"82/352"));}
}
